from pathlib import Path
from html import escape as e
import re
root=Path(__file__).resolve().parents[1]
public=root/'public'
def photo(kind,label):
    if kind=='battery': return '<img class="battery-reference-image" src="/assets/battery-internal-reference.png" alt="Owner-supplied tubular battery cutaway showing the internal plastic components" loading="lazy"><small class="illustration-note">Owner-supplied visual reference · illustrative component anatomy</small>'
    return f'<div class="editorial-photo photo-{kind}" role="img" aria-label="{e(label)}"></div><small class="illustration-note">AI-created manufacturing illustration · not a facility photograph</small>'
def link(url,label):return f'<a class="story-link" href="{url}">{label} <span>↗</span></a>'
def cards(items):return '<div class="story-grid">'+''.join(f'<article class="story-card"><small>{i+1:02d} / ENGINEERED WITH PURPOSE</small><h3>{title}</h3><p>{copy}</p></article>' for i,(title,copy) in enumerate(items))+'</div>'
def section(id,kicker,title,content,dark=False):return f'<section class="story-block {"story-dark" if dark else ""}" id="{id}"><div class="story-wrap"><p class="story-kicker">{kicker}</p><h2>{title}</h2>{content}</div></section>'
nav='<header class="story-nav"><a class="story-brand" href="/">✳ SHAKTHI<small>ENTERPRISES</small></a><nav aria-label="Main navigation"><a href="/mould-making">Mould making</a><a href="/plastic-applications">Materials</a><a href="/machinery">Machinery</a><a href="/agriculture">Agriculture</a><a href="/crm">Workspace ↗</a><a href="/contact">Let’s talk ↗</a></nav></header>'
footer='<footer class="story-footer"><span>© 2026 Shakthi Enterprises · Bengaluru</span>'+''.join(f'<a href="/{slug}">{label}</a>' for slug,label in [('about','Company'),('services','Our work'),('mould-making','Mould making'),('plastic-applications','Material applications'),('battery-components','Battery components'),('machinery','Machinery'),('agriculture','Agriculture'),('quality','Quality'),('catalogue','Catalogue'),('contact','Contact')])+'</footer>'
def page(slug,kicker,title,intro,kind,body,jumps):
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title.replace('<br>',' '))} | Shakthi Enterprises</title><meta name="description" content="{e(intro)}"><meta name="theme-color" content="#f4f2e8"><link rel="icon" href="/assets/favicon.png"><link rel="stylesheet" href="/stories.css"><script type="module" src="/stories.js"></script></head><body class="story-body"><a class="story-link" style="margin-left:6vw" href="#details">Skip to details ↓</a>{nav}<main><section class="story-wrap story-hero"><div><p class="story-kicker">{kicker}</p><h1>{title}</h1><p>{intro}</p>{link('#details','Explore the details')}</div><figure style="margin:0">{photo(kind,'Illustrative '+kicker.lower())}</figure></section><nav class="story-jumps" aria-label="Page sections">{''.join(f'<a href="#{id}">{label} ↓</a>' for id,label in jumps)}</nav><div id="details">{body}</div><section class="story-cta"><div><p class="story-kicker">LET’S START WITH YOUR REQUIREMENT</p><h2>A better part starts with a better conversation.</h2></div>{link('/contact','Discuss your component')}</section></main>{footer}</body></html>'''
    (public/(slug+'.html')).write_text(html,encoding='utf-8')

mould_steps=[('Understand the component','We begin with a drawing, 3D model or reference sample. The intended use, assembly interfaces, appearance, quantity and delivery requirement shape the tooling brief. Open questions are resolved before a design is frozen.'),('Engineer for manufacture','Draft, wall transitions, ribs, bosses, parting lines and undercuts are reviewed with the proposed material. Gate position, shrinkage and ejection must work together, rather than being treated as separate decisions.'),('Develop the mould','The approved concept becomes a tool layout with cavity, core, runner, cooling and ejection systems. Machining and finishing focus on the functional surfaces that determine the quality of the part.'),('Trial, measure and refine','Initial trials establish whether the tool and process can meet the agreed criteria. First-article inspection, assembly checks and visible defects guide documented corrections and repeat trials.'),('Release and support','Approved samples, tool identity, component revision and process requirements are retained for production. Cleaning, maintenance, shot history and repairs help preserve the tool through its working life.')]
mould_body=section('approach','FROM COMPONENT TO CAVITY','A tool built around<br>the job it must do.','<p>Mould making connects product geometry with a repeatable manufacturing process. At Shakthi Enterprises, tool design, mould development and injection moulding are considered together, so practical production questions enter the conversation early.</p>'+cards([('Function first','We review how the part will fit, move, seal or support its assembly. Critical dimensions and appearance requirements become part of the tool brief.'),('Material aware','Shrinkage, flow, cooling and stiffness differ across materials and grades. The tool is developed around an approved polymer and application requirement.'),('Production ready','Cavity count, expected demand, changeovers, ejection and maintainability influence how the tool works on the production floor.')]))
mould_body+=section('process','DESIGN → TOOL → TRIAL','Five stages.<br>One connected process.','<div class="tool-process-controls" aria-label="Explore mould development stages">'+''.join(f'<button data-tool-step="{i}" data-title="{e(t)}" data-copy="{e(c)}" aria-pressed="{str(i==0).lower()}">{i+1:02d} / {t}</button>' for i,(t,c) in enumerate(mould_steps))+'</div><div class="tool-process-output" aria-live="polite"><h3>Understand the component</h3><p>'+mould_steps[0][1]+'</p></div><div class="detail-list">'+''.join(f'<article class="detail-step"><div><h3>{t}</h3><p>{c}</p></div></article>' for t,c in mould_steps)+'</div>',True)
mould_body+=section('anatomy','THE DETAILS INSIDE THE TOOL','Every feature<br>has a purpose.',cards([('Core & cavity','Define the internal and external surfaces of the part. Fits, finish and dimensional requirements guide the design and inspection of these working surfaces.'),('Runner & gate','Direct the melt into the cavity. Gate location, filling balance and trimming requirements are reviewed against the component geometry and appearance.'),('Cooling circuits','Manage heat removal through the tool. Cooling balance influences cycle time, shrinkage, distortion and consistency.'),('Ejection system','Releases the cooled part without unacceptable marks or distortion. Pin positions and support are considered alongside draft and part geometry.'),('Guidance & alignment','Guide pillars, bushes and locating features align the tool halves. The assembly must remain stable under the approved production conditions.'),('Serviceable inserts','Where appropriate, inserts make wear areas or design changes easier to maintain. Tool ownership, revision and repair history remain identifiable.')]))
mould_body+=section('brief','WHAT TO SHARE','Bring the idea.<br>We’ll ask the right questions.','<p>Share your drawing or sample, application, target material, expected volumes, mating parts, visible surfaces, critical dimensions, delivery dates and any existing tooling. If the material or geometry is still open, tell us what the component needs to achieve.</p><div class="story-tags"><span>2D drawing / 3D model</span><span>Revision & tolerances</span><span>Material & colour</span><span>Annual / batch demand</span><span>Assembly & inspection criteria</span></div>'+link('/machinery','See how tool and machine are matched'))
page('mould-making','TOOL DESIGN / DEVELOPMENT / SUPPORT','Moulds that<br>make the difference.','From the first component review to mould trials and production support, we connect the details that turn an idea into a repeatable moulded part.','tool',mould_body,[('approach','Our approach'),('process','Development process'),('anatomy','Inside the mould'),('brief','Your project brief')])

material_data=[('pp','PP / Polypropylene','Lightweight housings & covers','A candidate family for battery cases, general housings, caps and protective components. Select the grade against impact, temperature, chemical exposure, joining and UV requirements.'),('hdpe','HDPE / Polyethylene','Fittings & protective parts','A candidate for irrigation fittings, caps and tough protective parts. Pressure duty, stress cracking, creep and outdoor exposure must be reviewed for the chosen grade and geometry.'),('abs','ABS','Visible equipment components','Often considered for rigid covers, housings and cosmetic components. Surface finish and impact requirements must be balanced with heat, weathering and chemical compatibility.'),('pa','PA / Polyamide','Mechanical & electrical components','An engineering material family for parts requiring mechanical performance, heat resistance or wear resistance. Moisture conditioning and reinforcement can materially affect dimensions.'),('pom','POM / Acetal','Precision moving parts','A candidate for gears, clips, bushes and mechanisms. Review friction, wear, dimensional stability, mating surfaces and long-term operating load before approving a grade.')]
material_body=section('selection','MATERIAL EXPLORER','Start with the application.<br>Then choose the grade.','<p>A polymer name alone does not define performance. Grade, additives, colour, reinforcement, processing, geometry and the operating environment all influence the finished part. The explorer introduces candidate material families; final selection uses supplier data and component validation.</p><div class="material-pills" aria-label="Explore polymer families">'+''.join(f'<button data-material="{key.upper()}" aria-pressed="{str(i==0).lower()}">{name}</button>' for i,(key,name,_,_) in enumerate(material_data))+'</div><div id="material-output" class="material-output" aria-live="polite"><h3>Polypropylene / PP</h3><p>Explore lightweight moulded housings, battery-container concepts, caps and protective components. Approval depends on the selected grade and the complete application.</p><a href="#pp">Explore PP applications ↗</a></div>')
for key,name,title,copy in material_data:
    material_body+=section(key,name,title, '<div class="story-split"><div><p>'+copy+'</p><h3>What we review with you</h3><p>Service temperature, impact or static load, dimensional tolerance, surface finish, environmental exposure, assembly method and expected life. We also review drying, shrinkage and processing requirements from the material supplier.</p>'+link('/contact','Discuss a material requirement')+'</div><figure style="margin:0">'+photo('material','Illustrative polymer pellets and moulded components')+'</figure></div>')
material_body+=section('applications','MATERIALS IN CONTEXT','Designed around<br>real working conditions.',cards([('Battery component concepts','Cases, lids and interfaces need a verified material, joining method and dimensional specification. Explore the moulded plastic parts in our interactive case study.'),('Agricultural components','Fittings and protective parts face sunlight, moisture, handling and sometimes chemicals. UV stabilisation and application-specific testing are part of the brief.'),('Industrial components','Covers, brackets and moving parts bring different demands for fit, strength, wear and appearance. Grade choice follows the complete component specification.')])+link('/agriculture','Explore agricultural applications')+' '+link('/battery-components','Explore battery components'))
material_body+=section('references','TECHNICAL BACKGROUND','Use the supplier’s data.','<p>Examples on this page describe candidate applications, not universal material guarantees or a confirmed production catalogue. We approve the specific component and grade with the customer.</p><p class="story-sources">Technical background: <a href="https://plastics-rubber.basf.com/global/en/performance_polymers/industries/pp_electronics_and_electric/products/ultramid">BASF — Ultramid polyamides</a> · <a href="https://www.lyondellbasell.com/en/our-solutions/technologies/petrochemical/polypropylene-technologies/">LyondellBasell — polypropylene technologies</a></p>')
page('plastic-applications','POLYMERS / PERFORMANCE / PURPOSE','The right material.<br>For its real world.','Explore how material selection, component design and injection moulding work together across battery, agricultural and industrial applications.','material',material_body,[('selection','Material explorer'),('pp','PP'),('hdpe','HDPE'),('abs','ABS'),('pa','PA'),('pom','POM'),('applications','Applications')])
# Preserve the established materials URL with the expanded content.
(public/'materials.html').write_text((public/'plastic-applications.html').read_text(encoding='utf-8'),encoding='utf-8')

battery_parts=[('case','The outer case','The structural envelope.','The moulded case houses the battery assembly and establishes the overall dimensions and mounting interface. Wall consistency, impact behaviour and material compatibility are reviewed against the customer’s design.','Check the envelope, wall transitions, material grade, mounting features and the assembly’s required tests.'),('lid','The top cover','A precise joining surface.','The lid closes the plastic enclosure and carries interfaces specified by the battery designer. The case-to-cover joint must suit the approved assembly and sealing process.','Check the joint geometry, cover flatness, process allowance and matching case revision.'),('partitions','Internal partitions','Six compartments, clearly defined.','The illustrative case contains six compartments. Moulded internal walls define their separation and must align with the rest of the approved assembly.','Check partition position, wall thickness, tool filling and distortion against the drawing.'),('terminals','Terminal interfaces','The connection starts with the fit.','Moulded openings, seats or surrounding features locate the customer’s electrical connections. This page illustrates the plastic interface; it does not claim that Shakthi manufactures conductive posts or complete batteries.','Check the interface drawing, insert requirements, clearances and assembly process with the battery designer.'),('vents','Vent & fill interfaces','Openings with a defined purpose.','The customer’s battery design determines the vent and fill arrangements. The moulded cover must reproduce the approved seats and openings consistently.','Validate the complete battery’s venting and safety requirements with the responsible designer; the illustration is not a functional vent specification.'),('ribs','Ribs & mounting features','Support, without unnecessary mass.','Ribs and locating features support the moulded component and help position it in its installation. Balanced transitions, radii and draft help the tool release the part while managing local stress.','Check rib proportions, sink risk, mounting load, clearances and the tool’s ejection requirements.')]
battery_parts += [
 ('housings','Vent plug housings','A seat for every vent plug.','The black cell-cap housings shown in the reference locate the vent plug assemblies above the cover. The moulded fit follows the approved mating geometry.','Review the seat, fit, thread or fastening detail and the specified assembly process.'),
 ('retainers','Tubular gauntlet retainers','Locating the internal assembly.','The reference identifies plastic retainers around the tubular internal components. The study separates them from the cover to make their location visible.','Confirm the customer drawing, material specification and fit to the internal assembly.'),
 ('separators','Separator envelopes','Separation within each cell.','The reference shows separator envelopes between internal elements. They are shown for context; their manufacture and material process differ from injection-moulded case parts.','Validate the separator specification with the responsible battery designer and supplier.'),
 ('handles','Plastic handle grips','A practical handling interface.','The reference combines side ropes with plastic hand grips. The geometry must suit its fixing points and the intended handling requirements.','Review grip shape, retention, fixing interfaces and the specified handling validation.'),
 ('panel','Front label panel recess','The identity of the product.','A recessed front panel locates the label and creates a defined presentation surface on the moulded jar. It is part of the external case geometry.','Review panel flatness, radii, texture and label placement with the approved artwork.')]
battery_body=section('scope','A PLASTIC COMPONENT CASE STUDY','Explore the enclosure.<br>Understand the purpose.','<p>This is an illustrative tall tubular battery component study for explaining injection-moulded plastic parts. It is not a battery product specification, an electrical assembly guide or a claim of complete-battery manufacture. Geometry, materials and performance must follow the customer-approved drawing and validation plan.</p>'+link('/#battery-journey','Return to the interactive 3D assembly'))
battery_body+=section('reference-views','YOUR BATTERY / TWO WAYS TO EXPLORE','Inside the case.<br>Above every component.','<p>The supplied visual references guide the tall white ribbed jar, black cover, six vent plugs, handle grips and internal component layout in the homepage study.</p><div class="reference-tabs" aria-label="Battery reference views"><button data-reference-view="internal" aria-pressed="true">Internal cutaway</button><button data-reference-view="exploded" aria-pressed="false">Exploded components</button></div><a id="battery-reference-link" href="/assets/battery-internal-reference.png" target="_blank" rel="noopener"><img id="battery-reference-image" class="battery-reference-image" src="/assets/battery-internal-reference.png" alt="Owner-supplied internal cutaway of a tubular battery with component labels" loading="lazy"></a><p class="illustration-note">Owner-supplied concept references. Open the image for a closer view.</p>')
for key,title,sub,copy,check in battery_parts:
    battery_body+=section(key,'COMPONENT / '+key.upper(),title, '<div class="story-split"><div><h3>'+sub+'</h3><p>'+copy+'</p><h3>Design & inspection focus</h3><p>'+check+'</p>'+link('/mould-making','How the mould is developed')+'</div><figure style="margin:0">'+photo('battery','Illustrative battery case and lid with internal compartments')+'</figure></div>')
page('battery-components','PRODUCT ANATOMY / MOULDED PLASTICS','A closer look.<br>At every part.','Scroll through the enclosure, cover, partitions and interfaces of an illustrative battery case, and see what each feature asks of the mould and material.','battery',battery_body,[('scope','The case study'),('reference-views','Reference views')]+[(key,title) for key,title,*_ in battery_parts])

machine_body=section('capacity','SIX MACHINES / CONNECTED OPERATIONS','Capacity is more<br>than a tonnage number.','<p>Clamping force is one part of machine selection. The mould’s dimensions, tie-bar clearance, mounting, opening stroke and ejection requirements must fit. Shot capacity, plasticising capability, material, projected area and the approved process window also influence the choice.</p><label for="capacity-range"><strong>Explore the clamping-force range</strong></label><input class="capacity-range" id="capacity-range" type="range" min="40" max="500" value="90" step="10"><div class="machine-result" aria-live="polite"><h3 id="capacity-value">90 tonnes</h3><p id="capacity-copy">Explore the register below.</p><small>This is a navigation aid, not an engineering machine-selection calculation.</small></div>'+cards([('Tooling operations / 40 tonnes','Compact moulding capacity. Technical compatibility is reviewed against the actual tool, material and approved shot requirement.'),('Tooling operations / 90 tonnes','Intermediate capacity for suitable components and tools. Exact model, platen, stroke and shot specifications must be confirmed.'),('Tooling operations / 90-tonne servo','Servo machine option in the operating register. Process capability and production allocation are reviewed for the specific part.'),('Production operations / 180-tonne Tokima','A production-machine entry for intermediate moulding requirements. Use the confirmed equipment specification for planning.'),('Production operations / 180-tonne servo','Additional servo production capacity. The mould, machine condition, operator availability and cycle-time plan remain linked.'),('Production operations / 500 tonnes','The largest clamping-force entry in the current register. Larger does not automatically mean suitable: tool fit and process limits still need review.')]))
machine_body+=section('cycle','INSIDE THE PRODUCTION CYCLE','Four steps.<br>A repeatable result.','<div class="process-controls" aria-label="Injection moulding cycle">'+''.join(f'<button data-cycle="{i}" aria-pressed="{str(i==0).lower()}">{label}</button>' for i,label in enumerate(['Clamp','Inject & pack','Cool','Open & eject']))+'</div><div id="process-output" class="process-output" aria-live="polite"><h3>01 / Clamp & prepare</h3><p>The mould closes and the clamping system holds the halves together. Approved material preparation, tool condition and machine setup establish the starting point.</p></div><p class="story-sources">Process background: <a href="https://www.engelglobal.com/en/gb/products/injection-moulding-processes">ENGEL — injection moulding processes</a>.</p>')
machine_body+=section('planning','FROM CAPACITY TO COMMITMENT','A plan the floor<br>can actually follow.',cards([('Match','Link the component, approved revision, mould and technically compatible machine. Select the correct operations and an active assigned operator.'),('Check','Review cycle-time capacity, setup allowance, existing jobs, mould availability and planned maintenance. A conflict needs a revised plan.'),('Follow through','Record actual shift production, inspect output and release accepted stock. Dispatch and commercial records follow the controlled workflow.')])+link('/crm#planner','Open the production task calendar'),True)
page('machinery','MACHINE REGISTER / PROCESS / CAPACITY','The machine.<br>The mould.<br>The right match.','Explore our six-machine operating register and how equipment, tools, materials and people come together in the production plan.','machine',machine_body,[('capacity','Machine register'),('cycle','Moulding cycle'),('planning','Production planning')])
(public/'infrastructure.html').write_text((public/'machinery.html').read_text(encoding='utf-8'),encoding='utf-8')

agri_body=section('needs','BUILT AROUND THE FIELD','Small components.<br>Practical responsibilities.','<p>Agricultural components are shaped by use: how they connect, how they are handled, how long they remain outdoors and what they encounter in service. We discuss the component requirement before selecting a material or committing a tool.</p>'+cards([('Irrigation connections','Candidate applications include connectors, adapters, caps and protective fittings. Mating dimensions, sealing geometry and any pressure duty must be specified and validated.'),('Crop & nursery support','Candidate moulded parts include support clips, tray concepts and protective items. Handling, cleaning, sunlight and expected service life influence the brief.'),('Equipment protection','Covers, guards, knobs and brackets can support agricultural equipment. Fit, vibration, impact and environmental exposure determine the design requirements.')]))
agri_body+=section('material','MATERIAL MEETS ENVIRONMENT','Sun. Water. Handling.<br>Plan for all three.','<div class="story-split"><figure style="margin:0">'+photo('agriculture','Illustrative irrigation fittings and nursery plants')+'</figure><div><p>Outdoor use can require UV-stabilised grades. Moisture, fertilisers, cleaning agents and temperature cycles add further questions. A resin family alone is not evidence that a component is suitable for a pressure system, drinking water or chemical contact.</p><p>We review the approved grade, drawing and required validation with the customer. Any regulated or certified use requires the appropriate supporting evidence for the complete product.</p>'+link('/plastic-applications','Explore materials & their applications')+'</div></div>')
agri_body+=section('development','TURN THE REQUIREMENT INTO A BRIEF','From field need<br>to moulded component.',cards([('Describe the application','Tell us the mating equipment, exposure, expected load, service life and installation method. Bring an existing sample if available.'),('Approve the design','Review the drawing, tolerances, material, colour and functional checks. Clarify any testing or certification required before tooling.'),('Trial in context','Assess samples in the intended assembly and operating conditions. Approved results guide the production release and inspection plan.')])+link('/mould-making','Explore the development process'),True)
page('agriculture','AGRICULTURAL NEEDS / MATERIAL APPLICATIONS','Made for work.<br>Out in the world.','Explore moulded component possibilities for irrigation, crop support and agricultural equipment, developed around the conditions in which they will be used.','agriculture',agri_body,[('needs','Application needs'),('material','Outdoor materials'),('development','Development path')])

about_body=section('company','SHAKTHI ENTERPRISES / BENGALURU','One manufacturing partner.<br>A connected way of working.','<p>Shakthi Enterprises brings tool design, mould development, plastic injection moulding and assembly into one manufacturing conversation. Established in 2006 and based in Bengaluru, the company works across Tooling operations and Production operations.</p><p>Our work starts with understanding what the component needs to do. The drawing, sample, application, material and quantity become the common reference for engineering, tooling, production and inspection. The goal is a part that can be made consistently and assessed against clear criteria.</p>'+cards([('Tooling operations','Connects the engineering brief with mould development, trials, refinements and production-machine requirements. Tool identity, compatibility and maintenance remain part of the conversation.'),('Production operations','Connects approved components and tools with machine planning, shift output, quality checks, accepted stock, packing and delivery.'),('A shared standard','The same component revision, ownership, quality requirement and delivery commitment should follow the work from the first enquiry to the finished shipment.')]))
about_body+=section('work','OUR WORK / YOUR COMPONENT','The detail carries<br>through every stage.','<div class="story-split"><figure style="margin:0">'+photo('engineer','Illustrative component engineering and mould study')+'</figure><div><p>A good manufacturing relationship depends on clear decisions: what is approved, what has changed, which revision is current and what needs attention. We keep tooling and production connected so issues can be reviewed with the right context.</p><p>Our workspace brings orders, machines, moulds, materials, production, inspection, dispatch and commercial follow-through into one traceable view. This supports the people doing the work; it does not replace their engineering judgement.</p>'+link('/services','See how we work')+'</div></div>')
about_body+=section('principles','HOW WE APPROACH A PROJECT','Clear requirements.<br>Careful follow-through.',cards([('Discuss before deciding','We ask about the real application, not only the shape. Missing requirements are clarified before the tool or production plan is approved.'),('Review with evidence','Drawings, revisions, samples, inspections and documented changes make decisions easier to understand and repeat.'),('Stay connected','Tooling, machine planning, material control and quality checks inform one another throughout the component’s production journey.')]),True)
page('about','OUR COMPANY / OUR WORK','Thoughtful engineering.<br>In every part.','Bengaluru-based tool design, mould development and plastic injection moulding, connected from the first idea to the final delivery.','engineer',about_body,[('company','Our company'),('work','Our work'),('principles','Our approach')])

service_body=section('engineer','01 / DESIGN & ENGINEER','Begin with the<br>right questions.','<div class="story-split"><div><p>We review the component’s purpose, drawing or reference sample, mating parts and material requirements. Draft, ribs, wall transitions, fastening, appearance and dimensional priorities are discussed before the tool concept is frozen.</p><p>The outcome is a practical brief: approved revision, proposed material, critical dimensions, production quantity and an inspection approach that can guide the next stage.</p>'+link('/mould-making#approach','Explore the engineering approach')+'</div><figure style="margin:0">'+photo('engineer','Illustrative engineering review and precision component')+'</figure></div>')
service_body+=section('develop','02 / DEVELOP & REFINE','Build the tool.<br>Prove the detail.','<div class="story-split"><figure style="margin:0">'+photo('tool','Illustrative precision injection mould')+'</figure><div><p>Tool design, machining, assembly and trials connect the approved part with a working mould. First-article checks identify what needs refinement, whether that is a visible surface, a functional fit or a production issue.</p><p>Documented changes and repeat trials help establish the accepted sample and the tool’s production requirements. Repair and maintenance support keep the mould’s identity and history visible.</p>'+link('/mould-making#process','Explore mould development')+'</div></div>')
service_body+=section('deliver','03 / PRODUCE & DELIVER','Make consistently.<br>Deliver with context.','<div class="story-split"><div><p>The production plan links the right machine, mould, material and operator. Shift output enters inspection before it becomes accepted stock. Finishing, assembly and packing follow the agreed component requirements.</p><p>Delivery quantities, dates and documents are connected to the order. Quality-held pieces remain separate from dispatchable stock so production totals do not become delivery promises before inspection.</p>'+link('/machinery','Explore the production process')+'</div><figure style="margin:0">'+photo('machine','Illustrative injection moulding machine')+'</figure></div>')
service_body+=section('quality','A CONNECTED PRODUCTION JOURNEY','From the first brief.<br>To the final record.',cards([('Engineering inputs','Drawing, revision, material, application, tolerances and agreed samples define what the component must achieve.'),('Production evidence','Job planning, material issues, actual output and inspection decisions preserve the context of the batch.'),('Delivery follow-through','Accepted stock, packing, dispatch and acknowledgement connect the physical shipment with the client order.')])+link('/quality','Explore quality control'),True)
page('services','DESIGN / DEVELOP / PRODUCE','From your idea.<br>To a finished part.','Our work connects engineering decisions, mould development and injection moulding, with inspection and delivery considered throughout the process.','tool',service_body,[('engineer','Design & engineer'),('develop','Develop & refine'),('deliver','Produce & deliver'),('quality','Connected quality')])

quality_body=section('requirements','QUALITY STARTS BEFORE PRODUCTION','Agree on what<br>good looks like.','<p>The drawing, component revision, material specification and agreed sample establish the inspection basis. Critical dimensions, visual criteria and functional checks should be clear before the first production batch.</p>'+cards([('Incoming material','Identify the grade, owner, colour and batch. Received material remains separate from usable stock until the required acceptance checks are complete.'),('First article & process','Review the trial or setup sample against the approved criteria. Changes to tool, revision or process require the appropriate review before release.'),('In-process inspection','Record the production lot and inspection result. Accepted, rejected and held quantities remain distinct so a pending decision cannot be mistaken for released stock.')]))
quality_body+=section('release','INSPECT / HOLD / RELEASE','A decision that<br>follows the part.','<p>Production counts and quality acceptance are different records. Held output needs a documented review or reinspection. Only accepted stock is available for allocation and dispatch in the connected workflow.</p><p>Where a customer requires a specific report, gauge, test or traceability format, that requirement belongs in the component brief and inspection plan. Certifications and guaranteed capabilities should only be stated when supporting evidence is available.</p>'+link('/crm#quality','Open quality control'),True)
quality_body+=section('delivery','BEFORE IT LEAVES','Check the quantity.<br>Protect the component.',cards([('Correct identity','Match the component, revision, client order and delivery schedule before the shipment is confirmed.'),('Appropriate packing','Use the agreed piece count, protection and identification. Packing is part of the component’s delivery requirement.'),('Traceable dispatch','Retain shipment quantity, transport reference and acknowledgement so the delivery can be followed through the order.')]))
page('quality','QUALITY / TRACEABILITY / RELEASE','The details matter.<br>At every stage.','Clear inspection criteria, separate quality decisions and traceable stock help connect what was made with what is ready to deliver.','tool',quality_body,[('requirements','Inspection basis'),('release','Quality release'),('delivery','Delivery checks')])

