# Keep new public destinations discoverable alongside the established pages.
sitemap=public/'sitemap.xml'
if sitemap.exists():
    xml=sitemap.read_text(encoding='utf-8')
    match=re.search(r'<loc>(https?://[^/<]+)',xml)
    if match:
        origin=match.group(1)
        for slug in ['mould-making','plastic-applications','battery-components','machinery','agriculture']:
            url=origin+'/'+slug
            if '<loc>'+url+'</loc>' not in xml: xml=xml.replace('</urlset>','<url><loc>'+url+'</loc></url></urlset>')
        sitemap.write_text(xml,encoding='utf-8')

